import java.util.Scanner;

public class Main {
    public static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int mod = sc.nextInt();
        int mid = n * (n - 1) / 2;
        int limit = n * (n - 1);
        int[][] dp = new int[n + 1][limit + 1];
        int[][] dpNext = new int[n + 1][limit + 1];

        dp[1][mid] = 1;

        for (int i = 2; i <= n; i++) {
            int lowBound = mid - (i - 1) * (i - 2) / 2;
            int highBound = mid + (i - 1) * (i - 2) / 2;

            for (int x = lowBound; x <= highBound; x++) {
                for (int delta = -i + 1; delta < i; delta++) {
                    int index = x + delta;
                    if (0 <= index && index <= limit) {
                        dp[i][index] = (int) ((dp[i][index] + (long) dp[i - 1][x] * (i - Math.abs(delta))) % mod);
                    }
                }
            }

            for (int x = lowBound; x <= highBound; x++) {
                dpNext[i][x] = (int) ((long) dpNext[i - 1][x] * i % mod);
            }

            for (int x = lowBound; x <= highBound; x++) {
                for (int delta = 1; delta < i; delta++) {
                    int index = x - delta;
                    if (0 <= index && index <= limit) {
                        dpNext[i][index] = (int) ((dpNext[i][index] + (long) dp[i - 1][x] * (i - delta)) % mod);
                    }
                }
            }
        }

        long result = 0;
        for (int x = mid + 1; x <= limit; x++) {
            result = (result + dpNext[n][x]) % mod;
        }
        System.out.println(result);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}

